package ChessPieces;

import Constants.Piece;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Base64;

public class ChessPieces {
    private static final String WHITE_KING_64 = "data:image/png;base64,";
    private static final String WHITE_QUEEN_64 = "data:image/png;base64,";
    private static final String WHITE_ROOK_64 = "data:image/png;base64,";
    private static final String WHITE_BISHOP_64 = "data:image/png;base64,";
    private static final String WHITE_KNIGHT_64 = "data:image/png;base64,";
    private static final String WHITE_PAWN_64 = "data:image/png;base64,";
    private static final String BLACK_KING_64 = "data:image/png;base64,";
    private static final String BLACK_QUEEN_64 = "data:image/png;base64,";
    private static final String BLACK_ROOK_64 = "data:image/png;base64,";
    private static final String BLACK_BISHOP_64 = "data:image/png;base64,";
    private static final String BLACK_KNIGHT_64 = "data:image/png;base64,";
    private static final String BLACK_PAWN_64 = "data:image/png;base64,";

    public static BufferedImage get(Piece piece){
        String b64 = getBase64(piece);
        if (b64 == null || b64.equals("PASTE_BASE64_HERE")) {
            System.err.println("ChessPieces.ChessPieces: image not set yet for " + piece);
            return null;
        }
        try {
            if (b64.contains(",")) {
                b64 = b64.substring(b64.indexOf(",") + 1);
            }
            byte[] bytes = Base64.getDecoder().decode(b64);
            return ImageIO.read(new ByteArrayInputStream(bytes));
        } catch (Exception e) {
            System.err.println("ChessPieces.ChessPieces: failed to decode " + piece + " — " + e.getMessage());
            return null;
        }
    }

    public static String getBase64(Piece piece){
        return switch (piece) {
            case WHITE_KING -> WHITE_KING_64;
            case WHITE_QUEEN -> WHITE_QUEEN_64;
            case WHITE_ROOK -> WHITE_ROOK_64;
            case WHITE_BISHOP -> WHITE_BISHOP_64;
            case WHITE_KNIGHT -> WHITE_KNIGHT_64;
            case WHITE_PAWN -> WHITE_PAWN_64;
            case BLACK_KING -> BLACK_KING_64;
            case BLACK_QUEEN -> BLACK_QUEEN_64;
            case BLACK_ROOK -> BLACK_ROOK_64;
            case BLACK_BISHOP -> BLACK_BISHOP_64;
            case BLACK_KNIGHT -> BLACK_KNIGHT_64;
            case BLACK_PAWN -> BLACK_PAWN_64;
            default -> null;
        };
    }

}
